function id(){return 'id_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){const el=document.getElementById('toastRoot');el.innerHTML='<div class="toast">'+esc(s)+'</div>';setTimeout(()=>el.innerHTML='',2600)}
function roleLabel(r){return ({super_admin:'Super Admin',principal:'Principal',admin:'Admin',teacher:'Teacher',student:'Student',content_admin:'Content Admin'})[r]||r}
function canWrite(section){const r=current?.role;if(r==='super_admin')return true;if(r==='principal')return section!=='schools'&&section!=='schoolLogo';if(section==='attendance')return r==='teacher';const rules={staff:['admin'],classes:['admin'],students:['admin','teacher'],subjects:['admin','content_admin'],resources:['teacher','content_admin'],homework:['teacher'],classwork:['teacher'],reportCards:['teacher'],fees:['teacher'],onlineTests:['teacher'],announcements:['teacher'],settings:[]};return (rules[section]||[]).includes(r)}
function canSee(page){if(page==='schools')return current?.role==='super_admin';if(page==='attendance')return ['teacher','principal','super_admin'].includes(current?.role);if(current?.role==='student')return ['dashboard','profile','feedback','directory','resources','homework','announcements','reportCards','fees','onlineTests'].includes(page);return true}
