 if(!student)return toast('Select an active student');
 const doc={studentUid:student.id,studentName:student.name||student.email,studentEmail:student.email,title:String(fd.get('title')).trim(),message:String(fd.get('message')).trim(),dueDate:String(fd.get('dueDate')||''),createdBy:current.id,createdByName:current.name||current.email,createdAt:new Date().toISOString()};
 if(!doc.title||!doc.message)return toast('Enter a reminder title and message');
