async function submitFeedback(e){e.preventDefault();if(!current||!auth.currentUser)return toast('Please sign in again to submit feedback');const form=e.currentTarget,fd=new FormData(form),type=String(fd.get('type')||'Suggestion'),rating=Number(fd.get('rating')||5),message=String(fd.get('message')||'').trim();if(message.length<10)return toast('Please enter at least 10 characters');const button=document.getElementById('feedbackSubmit');if(button){button.disabled=true;button.textContent='Submitting…'}try{const ref=await fs.collection('feedback').add({schoolId:activeSchoolId,senderUid:current.id,senderName:String(current.name||'').slice(0,100),senderEmail:String(current.email||auth.currentUser.email||'').slice(0,254),senderRole:current.role,type,rating,message,status:'open',reply:'',createdAt:firebase.firestore.FieldValue.serverTimestamp(),repliedAt:null});const snap=await ref.get();db.feedback=(db.feedback||[]).concat([{id:ref.id,...snap.data()}]);form.reset();render();toast('Feedback submitted successfully')}catch(err){console.error(err);toast('Could not submit feedback: '+friendlyError(err))}finally{if(button){button.disabled=false;button.textContent='Submit feedback'}}}
async function replyToFeedback(form){if(current?.role!=='super_admin')return toast('Only the Super Admin can reply');const id=form.dataset.feedbackId,reply=String(new FormData(form).get('reply')||'').trim();if(reply.length<2)return toast('Write a reply first');try{await fs.collection('feedback').doc(id).update({reply,status:'replied',repliedAt:firebase.firestore.FieldValue.serverTimestamp(),repliedBy:current.id});const item=(db.feedback||[]).find(x=>x.id===id);if(item){item.reply=reply;item.status='replied';item.repliedAt={seconds:Math.floor(Date.now()/1000)}}render();toast('Reply saved')}catch(err){console.error(err);toast('Could not save reply: '+friendlyError(err))}}
